const upsertOverride = `-- name: UpsertOverride :exec
INSERT INTO core_user_permissions
  (id_core_users, id_core_permissions, granted, id_core_users_granted_by,
   granted_at, expires_at)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (id_core_users, id_core_permissions) WHERE deleted_at IS NULL
DO UPDATE SET
  granted = $3::bool,
  expires_at = $6::timestamptz,
  id_core_users_granted_by = $4::bigint,
  granted_at = $5::timestamptz,
  updated_at = $7::timestamptz
`

type UpsertOverrideParams struct {
	IDCoreUsers          int64              `json:"id_core_users"`
	IDCorePermissions    int64              `json:"id_core_permissions"`
	Granted              bool               `json:"granted"`
	IDCoreUsersGrantedBy int64              `json:"id_core_users_granted_by"`
	GrantedAt            pgtype.Timestamptz `json:"granted_at"`
	ExpiresAt            pgtype.Timestamptz `json:"expires_at"`
	Column7              pgtype.Timestamptz `json:"column_7"`
}

// Upsert override — pasangan unik (user, permission) baris hidup: baris
// lama di-UPDATE (ON CONFLICT ... WHERE deleted_at IS NULL — baris
// soft-delete tidak disentuh), persis drizzle target+targetWhere.
func (q *Queries) UpsertOverride(ctx context.Context, arg UpsertOverrideParams) error {
	_, err := q.db.Exec(ctx, upsertOverride,
		arg.IDCoreUsers,
		arg.IDCorePermissions,
		arg.Granted,
		arg.IDCoreUsersGrantedBy,
		arg.GrantedAt,
		arg.ExpiresAt,
		arg.Column7,
	)
	return err
}
